416	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
417	     * date already on such a business day is returned unchanged.
418	     *
419	     * @param date the date to adjust
420	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
421	     */
422	    private LocalDate toBusinessDay(LocalDate date) {
423	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
424	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
425	                || PUBLIC_HOLIDAYS.contains(date)) {
426	            date = date.plusDays(1);
427	        }
428	        return date;
429	    }
