455	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
456	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
457	     *
458	     * @param registrationDate the adjusted business-day registration date to count owners against
459	     * @return the number of existing owners carrying that registration date
460	     */
461	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
462	        return this.clinicService.findAllOwners().stream()
463	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
464	            .count();
