513	    /**
514	     * Builds the customer code assigned to a newly created owner. The code is formatted as
515	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
516	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
517	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
518	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
519	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
520	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
521	     * identity scheme needs.
522	     *
523	     * @param owner the owner being created, whose fields the code is derived from
524	     * @return the formatted customer code
525	     */
526	    private String customerCodeFor(Owner owner) {
527	        String region = owner.getRegion();
528	        String regionCode = region != null ? region : "UNKNOWN";
529	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
530	        return deduplicateCustomerCode(regionCode + "-" + hash8);
531	    }
532	
533	    /**
534	     * Ensures the computed {@code customerCode} is unique across existing owners. When the given base
535	     * code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is appended with the
536	     * smallest {@code n} of 2 or more that yields a code no existing owner already carries.
537	     *
538	     * @param baseCode the customer code computed for the owner being created
539	     * @return the base code when it is already unique, otherwise the de-duplicated code
540	     */
541	    private String deduplicateCustomerCode(String baseCode) {
542	        Set<String> existing = this.clinicService.findAllOwners().stream()
543	            .map(Owner::getCustomerCode)
544	            .filter(Objects::nonNull)
545	            .collect(Collectors.toSet());
546	        if (!existing.contains(baseCode)) {
547	            return baseCode;
548	        }
549	        int n = 2;
550	        while (existing.contains(baseCode + "-" + n)) {
551	            n++;
552	        }
553	        return baseCode + "-" + n;
554	    }
