557	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
558	     * with the owner being created, compared case-insensitively. The count is taken before the
559	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
560	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
561	     *
562	     * @param firstName the first name of the owner being created
563	     * @param lastName the last name of the owner being created
564	     * @return the number of pre-existing owners sharing the same first and last name
565	     */
566	    private int countNamesakes(String firstName, String lastName) {
567	        return (int) this.clinicService.findAllOwners().stream()
568	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
569	                && lastName.equalsIgnoreCase(existing.getLastName()))
570	            .count();
