573	    /**
574	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
575	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it is not a hard
576	     * household duplicate. A member that declared its household via {@code sharesHousehold} is a
577	     * deliberate addition to a known household, not a suspected duplicate, so it is never flagged.
578	     * Otherwise it is a possible duplicate when an existing owner shares its {@code lastName}
579	     * (compared case-insensitively) and its {@code postcode} while carrying a different (normalized)
580	     * {@code telephone}. When such an owner is found, {@code possibleDuplicate} is set {@code true}
581	     * and {@code possibleDuplicateOf} to the matching owner's id; otherwise {@code possibleDuplicate}
582	     * is set {@code false} and no matching id is recorded. An owner without a postcode can share no
583	     * postcode and is never a possible duplicate.
584	     *
585	     * @param owner the owner being created, already carrying its normalized telephone and postcode
586	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
587	     */
588	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
589	        owner.setPossibleDuplicate(false);
590	        owner.setPossibleDuplicateOf(null);
591	        if (sharesHousehold(ownerFieldsDto)) {
592	            return;
593	        }
594	        findPossibleDuplicate(owner).ifPresent(existing -> {
595	            owner.setPossibleDuplicate(true);
596	            owner.setPossibleDuplicateOf(existing.getId());
597	        });
598	    }
