600	    /**
601	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
602	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
603	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
604	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records the
605	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
606	     * {@link java.util.Optional#empty()} is returned.
607	     *
608	     * @param owner the owner being created, already carrying its normalized telephone and postcode
609	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
610	     */
611	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
612	        if (owner.getPostcode() == null) {
613	            return java.util.Optional.empty();
614	        }
615	        return this.clinicService.findAllOwners().stream()
616	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
617	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
618	                && owner.getPostcode().equals(existing.getPostcode())
619	                && !owner.getTelephone().equals(existing.getTelephone()))
620	            .findFirst();
621	    }
