623	    /**
624	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
625	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
626	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
627	     * the names of every offending field, which the exception advice renders as a 400 response
628	     * with an {@code errors} array.
629	     *
630	     * @param ownerFieldsDto the submitted owner fields
631	     */
632	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
633	        List<String> missing = new ArrayList<>();
634	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
635	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
636	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
637	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
638	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
639	        if (!missing.isEmpty()) {
640	            throw new RequiredFieldsMissingException(missing);
641	        }
642	    }
