650	    /**
651	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
652	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
653	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
654	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
655	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
656	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
657	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
658	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
659	     *
660	     * @param telephone the submitted telephone value
661	     * @return the normalized E.164 telephone
662	     */
663	    private String normalizeTelephone(String telephone) {
664	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
665	        String e164;
666	        if (cleaned.startsWith("+")) {
667	            e164 = "+" + cleaned.substring(1);
668	        } else {
669	            String national = cleaned;
670	            if (national.startsWith("0")) {
671	                national = national.substring(1);
672	            }
673	            e164 = "+61" + national;
674	        }
675	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
676	            throw new InvalidFieldsException(List.of("telephone"));
677	        }
678	        validateNationalNumberLength(e164);
679	        return e164;
680	    }
681	
682	    /**
683	     * Validates the national-number length of an already syntactically valid E.164 telephone
684	     * against its country code. When the number carries a country code this application recognizes
685	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
686	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
687	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
688	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
689	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
690	     * that is not recognized carries no per-country length rule and is left to the general
691	     * 8-to-15-digit E.164 check.
692	     *
693	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
694	     */
695	    private void validateNationalNumberLength(String e164) {
696	        String countryCode = Owner.countryCodeOf(e164);
697	        if (countryCode == null) {
698	            return;
699	        }
700	        int nationalLength = e164.length() - 1 - countryCode.length();
701	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
702	            throw new InvalidFieldsException(List.of("telephone"));
703	        }
704	    }
