706	    /**
707	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
708	     * and a domain containing at least one dot, none of the parts holding whitespace or a
709	     * second {@code @}.
710	     */
711	    private static final java.util.regex.Pattern EMAIL_PATTERN =
712	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
713	
714	    /**
715	     * Disposable email domains an owner may not register with. An email whose domain (compared
716	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
717	     */
718	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
719	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
720	
721	    /**
722	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
723	     * accepted and returned unchanged. When present it must be a syntactically valid address
724	     * whose domain is not on the disposable-domain blocklist (see
725	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
726	     * present but syntactically invalid or on a disposable domain an
727	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
728	     * response naming the {@code email} field.
729	     *
730	     * @param email the submitted email value, or {@code null} when omitted
731	     * @return the lower-cased email, or {@code null} when none was supplied
732	     */
733	    private String normalizeEmail(String email) {
734	        if (email == null) {
735	            return null;
736	        }
737	        String trimmed = email.trim();
738	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
739	            throw new InvalidFieldsException(List.of("email"));
740	        }
741	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
742	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
743	            throw new InvalidFieldsException(List.of("email"));
744	        }
745	        return canonicalEmail(trimmed);
746	    }
747	
748	    /**
749	     * Reduces an email to the canonical form used both to store it and to compare it against
750	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
751	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
752	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
753	     * value read back off an existing owner without risk of rejecting it. This is the single
754	     * definition of email identity: two emails denote the same address exactly when they
755	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
756	     * an email already on an existing owner can be compared for equality after both pass through
757	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
758	     *
759	     * @param email the email to canonicalize, or {@code null} when none was supplied
760	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
761	     */
762	    private String canonicalEmail(String email) {
763	        if (email == null) {
764	            return null;
765	        }
766	        return email.trim().toLowerCase(java.util.Locale.ROOT);
767	    }
