769	    /**
770	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
771	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
772	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
773	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
774	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
775	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
776	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
777	     * 400 response naming the {@code postcode} field.
778	     *
779	     * @param postcode the submitted postcode, or {@code null} when omitted
780	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
781	     */
782	    private void validatePostcode(String postcode, String city) {
783	        if (postcode == null) {
784	            return;
785	        }
786	        if (!postcode.matches("^[0-9]{4}$")) {
787	            throw new InvalidFieldsException(List.of("postcode"));
788	        }
789	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
790	        if (range != null) {
791	            int value = Integer.parseInt(postcode);
792	            if (value < range[0] || value > range[1]) {
793	                throw new InvalidFieldsException(List.of("postcode"));
794	            }
795	        }
796	    }
