798	    /**
799	     * Rejects a new owner that would join a household already occupied by an existing owner. The
800	     * household is keyed on {@code (lastName, postcode)} and identified by the deterministic
801	     * {@code householdId} the owner would receive (see {@link #householdIdFor(String, String)}), so
802	     * two owners sharing a last name and postcode belong to the same household. When any existing
803	     * owner already carries that household identifier the new owner is a household duplicate and a
804	     * {@link DuplicateIdentityException} is thrown, which the exception advice renders as a 409
805	     * Conflict response. Setting {@code sharesHousehold} declares the owner a deliberate member of
806	     * that household and bypasses this block, so it is created rather than rejected. An owner without
807	     * a postcode belongs to no shared household and is never a household duplicate.
808	     *
809	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
810	     */
811	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
812	        if (sharesHousehold(ownerFieldsDto)) {
813	            return;
814	        }
815	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
816	        if (householdId == null) {
817	            return;
818	        }
819	        boolean taken = this.clinicService.findAllOwners().stream()
820	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
821	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
822	        if (taken) {
823	            throw new DuplicateIdentityException(householdId);
824	        }
825	    }
