840	    /**
841	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
842	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
843	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
844	     * every rule that treats a declared household member differently from an independent owner.
845	     *
846	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
847	     * @return {@code true} when the request opted into sharing a household
848	     */
849	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
850	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
851	    }
