853	    /**
854	     * Derives the stable {@code householdId} shared by every owner in the household identified by
855	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
856	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
857	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
858	     * postcode — regardless of creation order or address — resolve to the same identifier
859	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
860	     * returned.
861	     *
862	     * @param lastName the household's last name
863	     * @param postcode the household's postcode, or {@code null} when the owner has none
864	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
865	     */
866	    private String householdIdFor(String lastName, String postcode) {
867	        if (postcode == null) {
868	            return null;
869	        }
870	        return shaHex(householdKey(lastName, postcode), 12);
871	    }
