873	    /**
874	     * Builds the canonical household key that identifies the household a {@code lastName} and
875	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
876	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
877	     * owner fields make up a household and how they are normalized;
878	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
879	     * owners in the same household resolve to the same key and therefore the same identifier.
880	     *
881	     * @param lastName the household's last name
882	     * @param postcode the household's postcode
883	     * @return the normalized household key
884	     */
885	    private String householdKey(String lastName, String postcode) {
886	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
887	    }
