889	    /**
890	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
891	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
892	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
893	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
894	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
895	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
896	     * an {@link IllegalStateException} is thrown.
897	     *
898	     * @param input the string to hash
899	     * @param hexChars the number of leading upper-case hex characters to return
900	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
901	     */
902	    private String shaHex(String input, int hexChars) {
903	        try {
904	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
905	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
906	            StringBuilder sb = new StringBuilder();
907	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
908	                sb.append(String.format("%02X", digest[i]));
909	            }
910	            return sb.substring(0, hexChars);
911	        }
912	        catch (java.security.NoSuchAlgorithmException e) {
913	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
914	        }
915	    }
916	
917	    /**
918	     * Counts the owners that belong to the household identified by the given {@code householdId},
919	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
920	     * of owners, so after a create it reflects the household's size including the newly persisted
921	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
922	     * household and yields {@code 0}.
923	     *
924	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
925	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
926	     */
927	    private int countHouseholdMembers(String householdId) {
928	        if (householdId == null) {
929	            return 0;
930	        }
931	        return (int) this.clinicService.findAllOwners().stream()
932	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
933	            .count();
934	    }
935	
936	    /**
937	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
938	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
939	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
940	     *
941	     * @param value the value to collapse, or {@code null}
942	     * @return the whitespace-collapsed value, never {@code null}
943	     */
944	    private String collapseWhitespace(String value) {
945	        if (value == null) {
946	            return "";
947	        }
948	        return value.trim().replaceAll("\\s+", " ");
949	    }
950	
951	    /**
952	     * Common street-type abbreviations expanded during address normalization, keyed by their
953	     * upper-cased token.
954	     */
955	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
956	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
957	
958	    /**
959	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
960	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
961	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
962	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
963	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
964	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
965	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
966	     * everywhere an address is stored or compared.
967	     *
968	     * @param address the submitted address value, or {@code null}
969	     * @return the normalized address, never {@code null}
970	     */
971	    private String normalizeAddress(String address) {
972	        if (address == null) {
973	            return "";
974	        }
975	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
976	        if (collapsed.isEmpty()) {
977	            return "";
978	        }
979	        String[] tokens = collapsed.split(" ");
980	        StringBuilder sb = new StringBuilder(collapsed.length());
981	        for (int i = 0; i < tokens.length; i++) {
982	            if (i > 0) {
983	                sb.append(' ');
984	            }
985	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
986	        }
987	        return sb.toString();
988	    }
989	}
